(function() {
    'use strict';

    // ---------------------------------------------------------------
    // Circular Economy Factory — Lumena Electronics
    // v1.1.0
    //   - take-back adoption ramp + kiosks in Q3/Q4 (EU 65% target now reachable)
    //   - capex drag no longer compounds into the structural EBITDA margin
    //   - cumulative capital envelope ($42M) actually enforced
    //   - crisis event is deterministic per team and visible in the UI
    //   - briefing/decision panel rebuilt via framework lifecycle hooks
    //     (calculateResults is now side-effect free -> safe for competition preview)
    //   - undo restores state and re-renders the correct quarter
    // ---------------------------------------------------------------

    class CircularEconomyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Circular Economy Factory';
            this.version = '1.2.0';

            this.BASE_TAKEBACK = 8;        // structural take-back rate at start
            this.RAMP_RATE = 0.10;         // quarterly adoption ramp on installed collection network
            this.CAPEX_DRAG = 0.3;         // margin points lost per $1M invested, current quarter only

            this.ROUNDS = [
                {
                    title_en: 'Q1 — Diagnose & Prioritize',
                    title_es: 'Q1 — Diagnosticar y Priorizar',
                    maxBudget: 15,
                    investments: [
                        { id: 'reverseLogistics', cost: 2.8, effects: { takeBack: 12, circMaterial: 3, customer: 2, carbon: -2 } },
                        { id: 'takeBackKiosks', cost: 5.2, effects: { takeBack: 8, investor: 5, customer: 1, carbon: -1 } },
                        { id: 'refurbishmentLine', cost: 3.1, effects: { refurb: 10, circRevenue: 3.5, ebitda: 0.8, circMaterial: 1.5 }, requiresTakeBack: 15 },
                        { id: 'digitalPassport', cost: 1.9, effects: { regulatory: 15, circMaterial: 2, investor: 3 } },
                        { id: 'modularDesign', cost: 4.5, effects: { refurb: 5, carbon: -3, orgAlign: -5 }, delayedRefurbBonus: 0.22 },
                        { id: 'eprSoftware', cost: 0.8, effects: { regulatory: 20, investor: 2 } }
                    ],
                    hasSpecialDecision: false
                },
                {
                    title_en: 'Q2 — Build the Infrastructure',
                    title_es: 'Q2 — Construir la Infraestructura',
                    maxBudget: 18,
                    investments: [
                        { id: 'reverseLogistics', cost: 2.8, effects: { takeBack: 10, circMaterial: 2, customer: 2, carbon: -2 } },
                        { id: 'takeBackKiosks', cost: 5.2, effects: { takeBack: 6, investor: 3, customer: 1, carbon: -1 } },
                        { id: 'refurbishmentLine', cost: 3.1, effects: { refurb: 8, circRevenue: 2.5, ebitda: 0.6, circMaterial: 1.2 }, requiresTakeBack: 15 },
                        { id: 'digitalPassport', cost: 1.9, effects: { regulatory: 10, circMaterial: 1, investor: 2 } },
                        { id: 'modularDesign', cost: 4.5, effects: { refurb: 3, carbon: -2, orgAlign: -3 }, delayedRefurbBonus: 0.15 },
                        { id: 'eprSoftware', cost: 0.8, effects: { regulatory: 12, investor: 1 } }
                    ],
                    hasSpecialDecision: true,
                    specialType: 'telcomax'
                },
                {
                    title_en: 'Q3 — Scale & Integrate',
                    title_es: 'Q3 — Escalar e Integrar',
                    maxBudget: 20,
                    investments: [
                        { id: 'reverseLogistics', cost: 2.8, effects: { takeBack: 8, circMaterial: 2, carbon: -1 } },
                        { id: 'takeBackKiosks', cost: 5.2, effects: { takeBack: 5, investor: 2, customer: 1, carbon: -1 } },
                        { id: 'refurbishmentLine', cost: 3.1, effects: { refurb: 6, circRevenue: 2, ebitda: 0.5, circMaterial: 1.0 }, requiresTakeBack: 15 },
                        { id: 'digitalPassport', cost: 1.9, effects: { regulatory: 8, circMaterial: 1 } },
                        { id: 'eprSoftware', cost: 0.8, effects: { regulatory: 8 } }
                    ],
                    hasSpecialDecision: true,
                    specialType: 'organizational'
                },
                {
                    title_en: 'Q4 — Measure, Report & Defend',
                    title_es: 'Q4 — Medir, Reportar y Defender',
                    maxBudget: 10,
                    investments: [
                        { id: 'reverseLogistics', cost: 2.8, effects: { takeBack: 5, carbon: -1 } },
                        { id: 'takeBackKiosks', cost: 5.2, effects: { takeBack: 4, customer: 1 } },
                        { id: 'refurbishmentLine', cost: 3.1, effects: { refurb: 4, circRevenue: 1.5, circMaterial: 0.8 }, requiresTakeBack: 15 },
                        { id: 'eprSoftware', cost: 0.8, effects: { regulatory: 5 } }
                    ],
                    hasSpecialDecision: true,
                    specialType: 'boardDefense'
                }
            ];

            this.CRISIS_EVENTS = [
                { id: 'contamination', effects: { takeBack: -4, investor: -8, customer: -3 } },
                { id: 'supplierDisruption', effects: { circMaterial: -3, carbon: 4, orgAlign: -5 } },
                { id: 'regulatoryAudit', effects: { regulatory: -10, investor: -5 } },
                { id: 'competitorLaunch', effects: { customer: -6, investor: -4 } },
                { id: 'mediaScandal', effects: { investor: -10, customer: -5 } },
                { id: 'workerStrike', effects: { orgAlign: -12, refurb: -5 } }
            ];

            this.TELCOMAX_COST = 6.2;
            this._periodsRun = 0;   // guards the undo-to-Q1 reseed (see initialize)
        }

        // ----------------------------------------------------------
        // Lifecycle
        // ----------------------------------------------------------
        _seedDomainState() {
            return {
                takeBack: 8,
                refurb: 2,
                ebitda: 9.2,
                ebitdaBase: 9.2,          // structural margin; capex drag is applied per-quarter, not compounded
                circRevenue: 0,
                carbon: 48,
                circMaterial: 0.3,
                regulatory: 12,
                investor: 42,
                customer: 71,
                orgAlign: 55,
                capitalAvailable: 42,
                capitalSpent: 0,
                score: 0,
                performance: { overallScore: 0, grade: 'Needs Improvement' },
                telcomaxAccepted: false,
                renewedLaunched: false,
                modularInvested: false,
                modularBonus: 0,
                crisisOccurred: false,
                crisisId: null,
                crisisPeriod: null,
                orgResponse: null,
                boardNarrative: null,
                investmentLog: [],
                ebitdaHistory: [],
                circRevenueHistory: [],
                takeBackHistory: [],
                carbonHistory: [],
                regulatoryHistory: [],
                investorHistory: [],
                customerHistory: [],
                orgAlignHistory: [],
                refurbHistory: [],
                circMaterialHistory: []
            };
        }

        initialize(state) {
            var isEmpty = !state.domainState || Object.keys(state.domainState).length === 0;
            var historyEmpty = !state.history || state.history.length === 0;

            // Fresh game, or undo back past Q1 (framework pops history to zero and
            // re-calls initialize but does NOT reset domainState itself).
            if (isEmpty || (historyEmpty && this._periodsRun > 0)) {
                state.domainState = this._seedDomainState();
                state.decisions = { selectedInvestments: [], totalSpent: 0, specialChoice: null };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { selectedInvestments: [], totalSpent: 0, specialChoice: null };
            }
            // Back-fill for records saved by v1.0.0 (no ebitdaBase).
            if (state.domainState && typeof state.domainState.ebitdaBase !== 'number') {
                state.domainState.ebitdaBase = state.domainState.ebitda;
            }

            this._syncUI(state);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('periodBadge', 'currentPeriod', function(v) { return 'Q' + v; });
            uiManager.bind('takeBackDisplay', 'domainState.takeBack', function(v) { return v.toFixed(0) + '%'; });
            uiManager.bind('refurbDisplay', 'domainState.refurb', function(v) { return v.toFixed(0) + '%'; });
            uiManager.bind('ebitdaDisplay', 'domainState.ebitda', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('circRevenueDisplay', 'domainState.circRevenue', function(v) { return '$' + v.toFixed(1) + 'M'; });
            uiManager.bind('carbonDisplay', 'domainState.carbon', function(v) { return v.toFixed(0) + ' kg'; });
            uiManager.bind('circMaterialDisplay', 'domainState.circMaterial', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('regulatoryDisplay', 'domainState.regulatory', function(v) { return v.toFixed(0) + '/100'; });
            uiManager.bind('investorDisplay', 'domainState.investor', function(v) { return v.toFixed(0) + '/100'; });
            uiManager.bind('customerDisplay', 'domainState.customer', function(v) { return v.toFixed(0) + '/100'; });
            uiManager.bind('orgAlignDisplay', 'domainState.orgAlign', function(v) { return v.toFixed(0) + '/100'; });

            // Re-render briefing / decisions from the framework lifecycle instead of a
            // setTimeout inside calculateResults (which fired after the framework had
            // already advanced the period, and also ran during competition preview).
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.periodManager && typeof sim.periodManager.addHook === 'function') {
                sim.periodManager.addHook('afterAdvance', function(st) { self._syncUI(st); });
            }
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                sim.eventBus.on('period:undone', function(st) { self._syncUI(st); });
            }
        }

        // ----------------------------------------------------------
        // Decisions
        // ----------------------------------------------------------
        validateDecisions(decisions) {
            var state = (window.mySimulation && window.mySimulation.state) || { currentPeriod: 1, domainState: {} };
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var ds = state.domainState || {};
            var selected = [];
            var totalCost = 0;

            var checkboxes = document.querySelectorAll('.circular-sim-inv-check:checked');
            for (var i = 0; i < checkboxes.length; i++) {
                var cb = checkboxes[i];
                selected.push(cb.getAttribute('data-inv-id'));
                totalCost += parseFloat(cb.getAttribute('data-inv-cost'));
            }

            var specialChoice = null;
            if (round.hasSpecialDecision) {
                if (round.specialType === 'telcomax') {
                    var telcoRadio = document.querySelector('input[name="telcomaxBid"]:checked');
                    specialChoice = telcoRadio ? telcoRadio.value : 'decline';
                } else if (round.specialType === 'organizational') {
                    var orgRadio = document.querySelector('input[name="orgResponse"]:checked');
                    specialChoice = orgRadio ? orgRadio.value : 'engage';
                } else if (round.specialType === 'boardDefense') {
                    var boardRadio = document.querySelector('input[name="boardNarrative"]:checked');
                    specialChoice = boardRadio ? boardRadio.value : 'transparent';
                }
            }

            var committed = totalCost + (specialChoice === 'accept' ? this.TELCOMAX_COST : 0);

            if (totalCost > round.maxBudget) {
                this._notify('budget_exceeded', 'warning');
                return false;
            }

            // Cumulative capital envelope — declared in domainState but never enforced in v1.0.0.
            var available = (typeof ds.capitalAvailable === 'number') ? ds.capitalAvailable : 42;
            var spent = (typeof ds.capitalSpent === 'number') ? ds.capitalSpent : 0;
            var remaining = available - spent;
            if (committed > remaining + 1e-9) {
                this._notify('capital_exceeded', 'warning');
                return false;
            }

            decisions.selectedInvestments = selected;
            decisions.totalSpent = totalCost;
            decisions.specialChoice = specialChoice;
            return true;
        }

        // ----------------------------------------------------------
        // Model (pure: no DOM writes, no Math.random)
        // ----------------------------------------------------------
        calculateResults(state) {
            var d = state.decisions || {};
            var ds = state.domainState;
            var period = state.currentPeriod || 1;
            var roundIdx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var selected = d.selectedInvestments || [];
            var periodCost = d.totalSpent || 0;
            var takeBackAtStart = ds.takeBack;   // gate is evaluated on the ENTERING collection rate
            var feedstockShort = false;

            for (var i = 0; i < selected.length; i++) {
                var invId = selected[i];
                var inv = null;
                for (var j = 0; j < round.investments.length; j++) {
                    if (round.investments[j].id === invId) { inv = round.investments[j]; break; }
                }
                if (!inv) continue;

                if (inv.requiresTakeBack && takeBackAtStart < inv.requiresTakeBack) {
                    var reduced = {};
                    for (var key in inv.effects) { reduced[key] = inv.effects[key] * 0.4; }
                    this._applyEffects(ds, reduced);
                    ds.investmentLog.push(invId + '_reduced');
                    feedstockShort = true;
                } else {
                    this._applyEffects(ds, inv.effects);
                    ds.investmentLog.push(invId);
                }

                if (invId === 'modularDesign') {
                    ds.modularInvested = true;
                    ds.modularBonus = Math.max(ds.modularBonus || 0, inv.delayedRefurbBonus || 0);
                }
            }

            // Q2: crisis event (deterministic per team) + TelcoMax PaaS bid
            var crisisIdThisPeriod = null;
            if (roundIdx === 1) {
                var crisis = this.CRISIS_EVENTS[this._crisisIndex(state)];
                ds.crisisOccurred = true;
                ds.crisisId = crisis.id;
                ds.crisisPeriod = period;
                crisisIdThisPeriod = crisis.id;
                this._applyEffects(ds, crisis.effects);

                if (d.specialChoice === 'accept') {
                    ds.telcomaxAccepted = true;
                    ds.circRevenue += 8.5;
                    ds.ebitdaBase += 1.5;
                    ds.investor += 10;
                    ds.customer += 5;
                    periodCost += this.TELCOMAX_COST;
                }
            }

            // Q3: organisational resistance
            if (roundIdx === 2 && d.specialChoice) {
                ds.orgResponse = d.specialChoice;
                if (d.specialChoice === 'restructure') {
                    ds.orgAlign += 18;
                    ds.ebitdaBase -= 0.8;
                    ds.customer += 3;
                } else if (d.specialChoice === 'engage') {
                    ds.orgAlign += 10;
                    ds.customer += 1;
                } else if (d.specialChoice === 'defer') {
                    ds.orgAlign -= 5;
                    ds.refurb -= 3;
                }
            }

            // Q4: payoffs and board narrative
            if (roundIdx === 3) {
                ds.boardNarrative = d.specialChoice || 'transparent';
                if (ds.regulatory >= 80) { ds.investor += 15; ds.customer += 5; }
                if (ds.takeBack >= 65) { ds.investor += 10; }
                if (ds.telcomaxAccepted) { ds.circRevenue += 4; ds.customer += 3; }
                if (ds.modularInvested) {
                    // delayedRefurbBonus was dead data in v1.0.0; it now drives the payoff.
                    var bonus = ds.modularBonus || 0.22;
                    ds.refurb += Math.round(bonus * 100 * 0.36 * 10) / 10;  // 0.22 -> ~7.9 pts of refurb rate
                    ds.ebitdaBase += bonus * 5.45;                          // 0.22 -> ~1.2 margin points
                }
                if (d.specialChoice === 'forward') { ds.investor += 8; }
                else if (d.specialChoice === 'transparent') { ds.investor += 5; }
                else { ds.investor += 2; }
            }

            // Collection-network adoption ramp: an installed network keeps recruiting
            // consumers quarter after quarter. Without this the EU 65% target was
            // mathematically unreachable (structural max was 57%).
            var ramp = 0;
            if (period > 1) {
                ramp = Math.max(0, ds.takeBack - this.BASE_TAKEBACK) * this.RAMP_RATE;
                ds.takeBack += ramp;
            }

            // Capital
            ds.capitalSpent += periodCost;

            // EBITDA: structural margin minus THIS quarter's capex drag (v1.0.0 subtracted
            // the drag from the running margin, so it compounded and the margin could only fall).
            var investmentDrag = periodCost * this.CAPEX_DRAG;
            ds.ebitdaBase = Math.min(25, Math.max(-5, ds.ebitdaBase));
            ds.ebitda = Math.min(25, Math.max(-5, ds.ebitdaBase - investmentDrag));

            ds.takeBack = Math.min(100, Math.max(0, ds.takeBack));
            ds.refurb = Math.min(100, Math.max(0, ds.refurb));
            ds.circRevenue = Math.max(0, ds.circRevenue);
            ds.carbon = Math.max(10, Math.min(60, ds.carbon));
            ds.circMaterial = Math.min(100, Math.max(0, ds.circMaterial));
            ds.regulatory = Math.min(100, Math.max(0, ds.regulatory));
            ds.investor = Math.min(100, Math.max(0, ds.investor));
            ds.customer = Math.min(100, Math.max(0, ds.customer));
            ds.orgAlign = Math.min(100, Math.max(0, ds.orgAlign));

            ds.ebitdaHistory.push(parseFloat(ds.ebitda.toFixed(1)));
            ds.circRevenueHistory.push(parseFloat(ds.circRevenue.toFixed(1)));
            ds.takeBackHistory.push(parseFloat(ds.takeBack.toFixed(1)));
            ds.carbonHistory.push(parseFloat(ds.carbon.toFixed(1)));
            ds.regulatoryHistory.push(parseFloat(ds.regulatory.toFixed(1)));
            ds.investorHistory.push(parseFloat(ds.investor.toFixed(1)));
            ds.customerHistory.push(parseFloat(ds.customer.toFixed(1)));
            ds.orgAlignHistory.push(parseFloat(ds.orgAlign.toFixed(1)));
            ds.refurbHistory.push(parseFloat(ds.refurb.toFixed(1)));
            ds.circMaterialHistory.push(parseFloat(ds.circMaterial.toFixed(1)));

            this._periodsRun++;

            var _r = {
                takeBack: ds.takeBack, refurb: ds.refurb, ebitda: ds.ebitda, circRevenue: ds.circRevenue,
                carbon: ds.carbon, regulatory: ds.regulatory, investor: ds.investor,
                customer: ds.customer, orgAlign: ds.orgAlign
            };
            var _p = this._scorePillars(_r, period);
            ds.performance = {
                overallScore: _p.totalScore, grade: _p.grade,
                financialScore: _p.financialScore, envScore: _p.envScore, regScore: _p.regScore,
                stratScore: _p.stratScore, execScore: _p.execScore
            };
            ds.score = _p.totalScore;

            return {
                score: _p.totalScore,
                overallScore: _p.totalScore,
                grade: _p.grade,
                period: period,
                quarterLabel: 'Q' + period,
                investmentsChosen: selected.join(', ') || 'None',
                capitalInvested: periodCost,
                capitalRemaining: Math.max(0, ds.capitalAvailable - ds.capitalSpent),
                takeBack: ds.takeBack,
                takeBackRamp: parseFloat(ramp.toFixed(2)),
                refurb: ds.refurb,
                ebitda: ds.ebitda,
                circRevenue: ds.circRevenue,
                circMaterial: ds.circMaterial,
                carbon: ds.carbon,
                regulatory: ds.regulatory,
                investor: ds.investor,
                customer: ds.customer,
                orgAlign: ds.orgAlign,
                crisisId: crisisIdThisPeriod,
                feedstockShort: feedstockShort,
                specialChoice: d.specialChoice || null
            };
        }

        _applyEffects(ds, effects) {
            if (effects.takeBack) ds.takeBack += effects.takeBack;
            if (effects.refurb) ds.refurb += effects.refurb;
            if (effects.ebitda) ds.ebitdaBase += effects.ebitda;   // structural, not the displayed margin
            if (effects.circRevenue) ds.circRevenue += effects.circRevenue;
            if (effects.carbon) ds.carbon += effects.carbon;
            if (effects.circMaterial) ds.circMaterial += effects.circMaterial;
            if (effects.regulatory) ds.regulatory += effects.regulatory;
            if (effects.investor) ds.investor += effects.investor;
            if (effects.customer) ds.customer += effects.customer;
            if (effects.orgAlign) ds.orgAlign += effects.orgAlign;
        }

        // Deterministic crisis: same team always gets the same Q2 event, so the
        // competition-mode preview matches the submitted result and facilitators can
        // reproduce a run. (v1.0.0 rolled Math.random() inside calculateResults.)
        _crisisIndex(state) {
            var seedStr = String(state.gameId || '') + '|' + String(state.userId || '') + '|' + String(state.teamName || '');
            var h = 2166136261;
            for (var i = 0; i < seedStr.length; i++) {
                h ^= seedStr.charCodeAt(i);
                h = (h * 16777619) >>> 0;
            }
            return h % this.CRISIS_EVENTS.length;
        }

