        // Five pillars, 100 points: Financial 25 / Environmental 20 / Regulatory 20 /
        // Strategic 20 / Execution 15. (v1.0.0 summed to a maximum of 110 while the
        // grade bands assumed a 100-point scale.)
        // Shared pillar calculator. express/results_utils.php :: express_resolveDomainScore()
        // reads domainState.performance.overallScore (or a top-level `score`), so the score
        // MUST be written into domainState every period or the instructor panel shows "—"
        // and the LTI grade is 0. v1.0.0 only computed it client-side at the very end.
        _scorePillars(r, periodsPlayed) {
            var financialScore = 5;
            if (r.ebitda >= 12) financialScore = 15;
            else if (r.ebitda >= 9) financialScore = 10;
            financialScore += Math.min(10, (r.circRevenue || 0) * 0.8);

            var envScore = 0;
            if (r.carbon <= 32) envScore = 10;
            else if (r.carbon <= 40) envScore = 6;
            envScore += Math.min(5, (r.takeBack || 0) * 0.08);
            envScore += Math.min(5, (r.refurb || 0) * 0.2);

            var regScore = 0;
            if (r.takeBack >= 65) regScore += 10;
            if (r.regulatory >= 80) regScore += 10;

            var stratScore = 0;
            if (r.customer >= 80) stratScore += 8;
            if (r.investor >= 70) stratScore += 8;
            stratScore += Math.min(4, (r.circRevenue || 0) * 0.3);

            var execScore = 0;
            if (r.orgAlign >= 70) execScore += 10;
            execScore += Math.min(5, (periodsPlayed || 1) * 1.25);

            var total = financialScore + envScore + regScore + stratScore + execScore;
            var grade = 'Needs Improvement';
            if (total >= 80) grade = 'Circular Leader';
            else if (total >= 60) grade = 'Strong Transformer';
            else if (total >= 40) grade = 'Emerging Circular';

            return {
                totalScore: Math.round(total),
                grade: grade,
                financialScore: Math.round(financialScore),
                envScore: Math.round(envScore),
                regScore: Math.round(regScore),
                stratScore: Math.round(stratScore),
                execScore: Math.round(execScore)
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var p = this._scorePillars(r, history.length);
            return {
                totalScore: p.totalScore,
                grade: p.grade,
                financialScore: p.financialScore,
                envScore: p.envScore,
                regScore: p.regScore,
                stratScore: p.stratScore,
                execScore: p.execScore,
                performance: p.grade,
                insights: [
                    r.takeBack >= 65 ? 'EU EPR compliance achieved - market access secured' : 'EU EPR compliance gap remains - market access at risk',
                    r.investor >= 70 ? 'Investor confidence restored' : 'Investor concerns unresolved',
                    (r.circRevenue || 0) > 10 ? 'Strong circular revenue streams established' : 'Circular revenue streams still nascent'
                ]
            };
        }

